<?php $type=$_GET['type']??'channels';$labels=['banners'=>'البنرات','categories'=>'التصنيفات','channels'=>'القنوات','matches'=>'المباريات','movies'=>'الأفلام','series'=>'المسلسلات','notifications'=>'الإشعارات'];if(!isset($labels[$type]))exit('Invalid');$page=$labels[$type];require __DIR__.'/includes/header.php';$items=db_read($type);?>
<div class="titlebar"><div><h1><?=$page?></h1><p class="muted">إضافة وتعديل وحذف وإظهار المحتوى.</p></div><a class="btn" href="form.php?type=<?=$type?>">＋ إضافة جديد</a></div>
